export function BusinessIntelligenceReadiness({mode}:{mode:'industry'|'zip'}){const[view,setView]=useState<BiReadiness|null>(null),[error,setError]=useState(false);useEffect(()=>{const controller=new AbortController();void runnerJson<BiReadiness>('/api/business-map/business-intelligence-readiness',{signal:controller.signal}).then(value=>{if(!controller.signal.aborted&&validBiReadiness(value))setView(value);else if(!controller.signal.aborted)setError(true);}).catch(reason=>{if(!controller.signal.aborted&&reason?.name!=='AbortError')setError(true);});return()=>controller.abort();},[]);if(!view)return <section aria-label={`${mode==='industry'?'Industry overlays':'ZIP denominator'} readiness`}><h3>{mode==='industry'?'Industry overlay readiness':'ZIP denominator readiness'}</h3><p role={error?'alert':'status'}>{error?'Verified retained readiness is unavailable; no counts, validity, or completion state is substituted.':'Verifying retained readiness…'}</p></section>;if(mode==='industry'){const p=view.pharmacy_overlay,f=view.fmcsa_transportation_membership,i=view.irs_tax_exempt_organization_membership;return <section aria-label="Industry overlay readiness"><h3>Verified non-additive industry memberships</h3><article aria-label="Pharmacy overlay readiness"><h4>Pharmacy</h4><p><strong>{count(p.summary.pharmacy_rows)}</strong> active NPI organization records as of {p.claims.active_npi_enumeration_as_of}; exact same-source registry identities.</p><p>Generic-business additions: {p.summary.generic_business_additivity_delta}. Completeness not established; no licensure, current-operation, physical-site, or USPS-validity claim.</p><details><summary>Pharmacy release</summary><p><code>{p.release_id}</code> · <code>{p.manifest_sha256}</code></p></details></article><article aria-label="FMCSA transportation membership readiness"><h4>Transportation · FMCSA membership</h4><p><strong>{count(f.summary.fmcsa_rows)}</strong> source-defined active registrations as of {f.claims.source_defined_active_fmcsa_registration_as_of}; exact USDOT, site, and establishment identity membership.</p><dl><dt>Generic-business additions</dt><dd>{f.summary.generic_business_additivity_delta}</dd><dt>ZIP evidence rows with membership</dt><dd>{count(f.summary.positive_zip5_rows)} / {count(f.summary.zip5_denominator_rows)}</dd><dt>Industry completeness</dt><dd>Not established</dd></dl><p>Distinct, non-additive transportation membership. Roles and classes overlap. This is not a unique-business count or proof of current operation, verified physical sites, carrier/transportation completeness, or USPS ZIP validity.</p><details><summary>FMCSA release</summary><p><code>{f.release_id}</code> · <code>{f.manifest_sha256}</code></p></details></article><article aria-label="IRS tax-exempt organization membership readiness"><h4>Tax-exempt organizations · IRS EO membership</h4><p><strong>{count(i.summary.irs_eo_rows)}</strong> current-extract organization records as of {i.claims.source_current_extract_membership_as_of}; exact EIN-to-registry organization membership.</p><dl><dt>Generic-business additions</dt><dd>{i.summary.generic_business_additivity_delta}</dd><dt>ZIP evidence rows with membership</dt><dd>{count(i.summary.positive_zip5_rows)} / {count(i.summary.zip5_denominator_rows)}</dd><dt>Industry completeness</dt><dd>Not established</dd></dl><p>Identifier-free aggregate filing-address evidence only. It is not a physical-site, current-operation, all-nonprofit, disclosure-control, or USPS-validity claim; small cells are not suppressed.</p><details><summary>IRS EO release</summary><p><code>{i.release_id}</code> · <code>{i.manifest_sha256}</code></p></details></article></section>;}const z=view.zip_denominator;return <section aria-label="ZIP denominator readiness"><h3>ZIP denominator readiness</h3><p><code>{z.status}</code>. All {count(z.retained_zip_evidence.rows)} registry ZIP evidence keys remain USPS-unverified; same-code Census ZCTA membership is not USPS validity.</p><dl><dt>Machine-readable blockers</dt><dd><ul>{z.blockers.map(blocker=><li key={blocker}><code>{blocker}</code></li>)}</ul></dd><dt>Authoritative current USPS denominator</dt><dd>Unknown</dd><dt>Valid USPS ZIP count</dt><dd>Unknown</dd></dl><details><summary>Verified retained release</summary><p><code>{z.release_id}</code> · observed {z.observed_at}</p><p>Readiness SHA-256: <code>{z.readiness_sha256}</code></p></details></section>;}

export function OutsideNationalReporting({comparison}:{comparison?:ScopeComparison}) {
  const ready=comparison?.available&&comparison.configuration&&comparison.catalog&&Array.isArray(comparison.industries);
  return <section aria-label="Outside national reporting denominator"><h3>Outside national reporting denominator</h3>
    <p>Configured industries below are excluded from the national reporting denominator. State-only configuration is not evidence of acquisition or nationwide coverage. Expected, measured and unmeasured matrix totals above are unchanged; no completeness percentage is inferred.</p>
    {!ready?<p role="status">Scope comparison unavailable. Missing or unverified inputs are not an empty gap list or zero coverage.</p>:<>
      <p>Compared denominator: {comparison.denominator_version}.</p>
      {comparison.industries!.length?<div className="representation-table" role="region" aria-label="Excluded configured industry sources" tabIndex={0}><table><caption>Configuration only — not acquired records or measured coverage</caption><thead><tr><th scope="col">Configured industry</th><th scope="col">Source configuration</th><th scope="col">Publisher scope</th></tr></thead><tbody>{comparison.industries!.flatMap(industry=>industry.sources.map(source=><tr key={`${industry.id}:${source.id}`}><th scope="row">{categoryLabel(industry.id)}</th><td>{source.id}{source.manual_selection_required&&' · manual selection required'}</td><td>{source.scope==='state'?`State-only: ${Array.isArray(source.publisher_states)?source.publisher_states.join(', '):'Unknown'}`:'National configuration only'}</td></tr>))}</tbody></table></div>:<p>No excluded configured industry groups were found in this validated comparison. This is not a completeness claim.</p>}
      <details><summary>Scope comparison identities</summary><p>Configuration: {comparison.configuration!.path} · version {comparison.configuration!.version}</p><p>Configuration SHA-256: <code style={{overflowWrap:'anywhere'}}>{comparison.configuration!.sha256}</code></p><p>Catalog: {comparison.catalog!.path} · {comparison.catalog!.schema_version} · {comparison.catalog!.denominator_version}</p><p>Validated base catalog SHA-256: <code style={{overflowWrap:'anywhere'}}>{comparison.catalog!.predecessor_sha256}</code></p></details>
    </>}
  </section>;
}

export function summarizeAvailability(rows:MatrixRow[]){
  const available=rows.reduce((sum,row)=>sum+row.available,0),measured=rows.reduce((sum,row)=>sum+row.measured,0),expected=rows.reduce((sum,row)=>sum+row.denominator,0),unmeasured=rows.reduce((sum,row)=>sum+row.unmeasured,0),connected=rows.filter(row=>row.available>0).length;
  return {available,measured,expected,unmeasured,connected,jurisdictions:rows.length,availabilityPercent:measured?available/measured*100:null,connectivityPercent:rows.length?connected/rows.length*100:null};
}

